rules_version = '2';
service cloud.firestore {
 match /databases/{database}/documents {
  match /books/{bookId} {
   allow read: if true;
   allow create, update: if request.resource.data.keys().hasOnly(['title','pages']) && request.resource.data.title is string && request.resource.data.pages is int && request.resource.data.pages > 0;
   allow delete: if false;
  }
 }
}

function bookLabel(data){
 if(!data || typeof data.title!=="string" || typeof data.pages!=="number")return "Book data is incomplete";
 return `${data.title}: ${data.pages} pages`;
}
console.log(bookLabel({title:"Moon Trip",pages:60}));
console.log(bookLabel({title:"Missing pages"}));
